const MinimizeProjectCard: React.FC<{ project: any; index: number }> = ({ project, index }) => {
  const cardRef = useRef<HTMLDivElement>(null);
  const [scale, setScale] = useState(1);
  const [opacity, setOpacity] = useState(1);

  useEffect(() => {
    const handleScroll = () => {
      if (!cardRef.current) return;

      const rect = cardRef.current.getBoundingClientRect();
      const viewportHeight = window.innerHeight;

      // When the card is nearing the top, it scales down to reveal the one underneath
      if (rect.top < 80) {
        const progress = Math.min(Math.max((80 - rect.top) / viewportHeight, 0), 1);
        const newScale = 1 - (progress * 0.12); 
        const newOpacity = 1 - (progress * 0.3); 
        setScale(newScale);
        setOpacity(newOpacity);
      } else {
        setScale(1);
        setOpacity(1);
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <div 
      ref={cardRef}
      className="sticky top-16 md:top-24 w-full px-4 md:px-12 lg:px-20 h-[80vh] flex items-center justify-center pointer-events-none"
      style={{ zIndex: index + 1 }}
    >
      <div 
        className="relative w-full max-w-[1600px] h-full rounded-[2.5rem] md:rounded-[4rem] overflow-hidden bg-[#0F211D] shadow-[0_40px_100px_-20px_rgba(0,0,0,0.5)] pointer-events-auto cursor-pointer transition-all duration-300 ease-out origin-center"
        style={{
          transform: `scale(${scale})`,
          opacity: opacity,
        }}
        onClick={() => window.open(project.link, '_blank')}
      >
        <div className="absolute inset-0 w-full h-full">
          <img 
            src={project.imageUrl} 
            alt={project.title}
            className="w-full h-full object-cover grayscale opacity-40 transition-all duration-1000 scale-110 hover:grayscale-0 hover:opacity-100 hover:scale-100"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-[#0F211D] via-[#0F211D]/40 to-transparent"></div>
        </div>

        <div className="absolute bottom-0 left-0 w-full p-8 md:p-16 lg:p-24 flex flex-col md:flex-row items-end justify-between gap-10">
          <div className="space-y-6 max-w-3xl">
            <div className="flex items-center gap-4">
              <span className="text-[10px] md:text-xs font-black text-[#D4FF3F] tracking-[0.5em] uppercase">{project.category}</span>
              <div className="h-px w-12 bg-[#D4FF3F]/30"></div>
            </div>

            <h3 className="text-5xl md:text-7xl lg:text-[7vw] font-heading font-black text-white leading-[0.8] tracking-tighter">
              {project.title.toUpperCase()}
            </h3>

            <p className="text-lg md:text-xl lg:text-3xl font-bold text-white/70 max-w-2xl leading-tight">
              {project.description}
            </p>

            <div className="flex flex-wrap gap-2 pt-4">
              {project.tags.map((tag: string) => (
                <span key={tag} className="text-[9px] font-black uppercase tracking-[0.2em] px-4 py-2 border border-white/20 text-white/60 rounded-full bg-white/5 backdrop-blur-md">
                  {tag}
                </span>
              ))}
            </div>
          </div>

          <div className="group/btn flex items-center gap-6 pb-2 self-start md:self-end">
            <div className="flex flex-col items-end">
                <span className="text-xs font-black uppercase tracking-[0.5em] text-white">Live View</span>
            </div>
            <div className="w-16 h-16 md:w-20 md:h-20 rounded-full bg-[#D4FF3F] flex items-center justify-center text-[#0F211D] transition-all duration-500 group-hover/btn:scale-110 group-hover/btn:rotate-45 shadow-2xl">
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round">
