import React, { useState, useEffect } from 'react';

const Header: React.FC = () => {
  const [scrolled, setScrolled] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navLinks = [
    { name: 'Start', href: '#hero' },
    { name: 'Works', href: '#projects' },
    { name: 'Expertise', href: '#services' },
    { name: 'Story', href: '#about' },
  ];

  const handleNavClick = (e: React.MouseEvent<HTMLAnchorElement>, href: string) => {
    e.preventDefault();
    setIsMenuOpen(false);
    const targetId = href.replace('#', '');
    const elem = document.getElementById(targetId);
    if (elem) {
      const offset = 80;
      const elementPosition = elem.getBoundingClientRect().top;
      const offsetPosition = elementPosition + window.pageYOffset - offset;

      window.scrollTo({
        top: offsetPosition,
        behavior: 'smooth'
      });
      window.history.pushState(null, '', href);
    }
  };

  return (
    <>
      <header className="fixed top-0 left-0 w-full z-[1000] px-6 md:px-12 lg:px-20 py-8 md:py-12 pointer-events-none">
        <div className={`max-w-[1800px] mx-auto flex justify-between items-center transition-all duration-700 pointer-events-auto ${scrolled ? 'opacity-0 -translate-y-4 pointer-events-none' : 'opacity-100'}`}>
          <a href="#hero" onClick={(e) => handleNavClick(e, '#hero')} className="font-heading font-black text-3xl tracking-tighter text-[#0F211D]">
            DANIEL S.
          </a>

          <nav className="hidden lg:flex items-center gap-12">
            {navLinks.map((link) => (
              <a
                key={link.name}
                href={link.href}
                onClick={(e) => handleNavClick(e, link.href)}
                className="text-[10px] font-black uppercase tracking-[0.4em] text-[#0F211D]/60 hover:text-[#0F211D] transition-colors"
              >
                {link.name}
              </a>
            ))}
            <a 
              href="#contact"
              onClick={(e) => handleNavClick(e, '#contact')}
              className="bg-[#0F211D] text-[#FDFCF0] px-8 py-4 rounded-full text-[10px] font-black uppercase tracking-widest hover:bg-[#2D5A27] transition-all"
            >
              Let's Talk
            </a>
          </nav>
        </div>

        {/* Floating Mini Menu when scrolled */}
        <div className={`fixed top-8 left-1/2 -translate-x-1/2 transition-all duration-700 pointer-events-auto flex items-center gap-2 p-2 bg-[#0F211D] rounded-full shadow-2xl border border-white/10 ${scrolled ? 'translate-y-0 opacity-100 scale-100' : '-translate-y-20 opacity-0 scale-90'}`}>
            <button 
              onClick={() => setIsMenuOpen(true)}
              className="px-6 py-2.5 text-[10px] font-black uppercase tracking-widest text-[#D4FF3F]"
            >
              Menu
            </button>
            <div className="w-px h-4 bg-white/20"></div>
            <a 
              href="#contact" 
              onClick={(e) => handleNavClick(e, '#contact')}
              className="px-6 py-2.5 text-[10px] font-black uppercase tracking-widest text-[#FDFCF0]"
            >
              Talk
            </a>
        </div>
      </header>

      {/* Mobile/Tablet Overlay (same as before but slightly cleaner) */}
